  g.append("line")
    .attr("x1", x(2020))
    .attr("x2", x(2020))
    .attr("y1", 0)
    .attr("y2", innerH)
    .attr("stroke", refColor)
    .attr("stroke-width", 1);

  // Title + subtitle (top-left)
  svg
    .append("text")
    .attr("x", margin.left)
    .attr("y", 16)
    .text("Fertility rate")
    .attr("fill", domainColor)
    .style("font-family", "sans-serif")
    .style("font-size", "14px")
    .style("font-weight", "600")
    .attr("text-anchor", "start");

  svg
    .append("text")
    .attr("x", margin.left)
    .attr("y", 34)
    .text("8 children per woman")
    .attr("fill", "#8a8a8a")
    .style("font-family", "sans-serif")
    .style("font-size", "12px")
    .attr("text-anchor", "start");

  // (3) Shaded region for 'One-child policy' (placed before lines so it's behind them)
  const oneChildPolicyStartYear = 1975;
  const oneChildPolicyEndYear = 1985;
  const oneChildPolicyLabelYear = (oneChildPolicyStartYear + oneChildPolicyEndYear) / 2;

  g.append("rect")
    .attr("x", x(oneChildPolicyStartYear))
    .attr("y", 0) // From top of chart area
    .attr("width", x(oneChildPolicyEndYear) - x(oneChildPolicyStartYear))
    .attr("height", innerH) // To bottom of chart area
    .attr("fill", colors.get("China")) // Use China's color, but very light
    .attr("opacity", 0.05);

  // Line generator
  const line = d3
    .line()
    .x((d) => x(d.year))
    .y((d) => y(d.value))
    .curve(d3.curveLinear);

  // Group by series
  const bySeries = d3.group(data, (d) => d.series);

  // Draw solid and projected segments separately
  for (const [series, pts] of bySeries) {
    const sorted = pts.slice().sort((a, b) => d3.ascending(a.year, b.year));
    const solid = sorted.filter((d) => d.year <= 2020);
    const proj = sorted.filter((d) => d.year >= 2020);

    // Solid
    g.append("path")
      .datum(solid)
      .attr("fill", "none")
      .attr("stroke", colors.get(series))
      .attr("stroke-width", 3)
      .attr("stroke-linecap", "round")
      .attr("stroke-linejoin", "round")
      .attr("d", line);

    // Projected (dotted)
    g.append("path")
      .datum(proj)
      .attr("fill", "none")
      .attr("stroke", colors.get(series))
      .attr("stroke-width", 3)
      .attr("stroke-linecap", "round")
      .attr("stroke-linejoin", "round")
      // small dots similar to the image
      .attr("stroke-dasharray", "1,6")
      .attr("d", line);
  }

  // --- ANNOTATIONS START HERE ---

  // (1) Label the orange line as 'India'
  g.append("text")
